const FR = [["Bouclier +1","equipment","<p>Tant que vous tenez ce bouclier, vous bénéficiez d'un bonus de +1 à la CA. Ce bonus s'ajoute au bonus normal du bouclier.</p>",{"armor.magicalBonus":1},[]],["Armure de cuir clouté +3","equipment","<p>Cette armure a été ornée de runes puissantes, forgée dans des feux ensorcelés ou bénie par un être puissant. Vous bénéficiez d'un bonus à la CA tant que vous portez cette armure.</p>",{"armor.magicalBonus":3},[]],["Cimeterre +2","weapon","<p>Vous avez un bonus aux jets d'attaque et de dégâts effectués avec cette arme magique.</p>",{"weapon.magicalBonus":2,"weapon.baseItem":"scimitar"},[],["effect"]],["Masse d'armes +1","weapon","<p>Vous avez un bonus aux jets d'attaque et de dégâts effectués avec cette arme magique.</p>",{"weapon.magicalBonus":1,"weapon.baseItem":"mace"},[],["effect"]],["Arc long +1","weapon","<p>Vous avez un bonus aux jets d'attaque et de dégâts effectués avec cette arme magique.</p>",{"weapon.magicalBonus":1,"weapon.baseItem":"longbow"},[],["effect"]],["Hache d'armes +3","weapon","<p>Vous avez un bonus aux jets d'attaque et de dégâts effectués avec cette arme magique.</p>",{"weapon.magicalBonus":3,"weapon.baseItem":"battleaxe"},[],["effect"]],["Baguette de toile d'araignée","equipment","<p>Baguette (nécessite un lien d'harmonisation avec un lanceur de sorts). Cette baguette possède 7 charges. Quand vous la tenez, vous pouvez utiliser une action et dépenser 1 charge pour lancer le sort Toile d'araignée (DD de sauvegarde 15). La baguette récupère 1d6 + 1 charges dépensées chaque jour à l'aube.</p>",{"attunement":"required","attunementCondition":"un lanceur de sorts"},[],["effect","consumable.type","consumable.charges","consumable.destroyOnEmpty"]],["Médaillon des pensées","equipment","<p>Objet merveilleux, peu commun (nécessite un lien d'harmonisation). Le médaillon possède 3 charges. Quand vous le portez, vous pouvez utiliser une action et dépenser 1 charge pour lancer Détection des pensées (DD de sauvegarde 13). Le médaillon récupère 1d3 charges dépensées chaque jour à l'aube.</p>",{"rarity":"uncommon","attunement":"required"},[],["effect","consumable.type","consumable.charges","consumable.destroyOnEmpty"]],["Anneau de résistance psychique","equipment","<p>(Nécessite un lien d'harmonisation) Cet anneau est serti d'une pierre de jade qui brille à la lumière. Vous avez la résistance aux dégâts psychiques tant que vous portez cet anneau.</p>",{"attunement":"required"},[{"kind":"resistance","scope":"psychic","value":null}]],["Potion de longévité","consumable","<p>Potion, très rare. Quand vous buvez cette potion, votre âge physique est réduit de 1d6 + 6 ans, jusqu'à un minimum de 13 ans. Chaque fois que vous buvez ensuite une potion de longévité, vous avez 10 % de chances cumulées de vieillir de 1d6 + 6 ans à la place.</p>",{"rarity":"veryRare","consumable.type":"potion"},[],["effect","consumable.charges","consumable.destroyOnEmpty"]],["Anneau de marche sur l'eau","equipment","<p>Anneau, peu commun. Tant que vous portez cet anneau, vous lancez Marche sur l'eau grâce à lui, en ne vous ciblant que vous-même.</p>",{"rarity":"uncommon"},[],["effect"]],["Bouclier de sentinelle","equipment","<p>Armure (bouclier), peu commun. Tant que vous tenez ce bouclier, vous avez l'avantage aux jets d'initiative et aux tests de Sagesse (Perception). Le bouclier est orné d'un symbole d'œil.</p>",{"rarity":"uncommon","armor.type":"shield"},[],["effect","armor.ac"]],["Lame de chance","weapon","<p>Arme (glaive, espadon, épée longue, rapière, cimeterre, serpe ou épée courte), légendaire (nécessite un lien d'harmonisation). Vous bénéficiez d'un bonus de +1 aux jets d'attaque et de dégâts effectués avec cette arme magique. Tant que l'arme est sur vous, vous bénéficiez aussi d'un bonus de +1 aux jets de sauvegarde.</p>",{"rarity":"legendary","attunement":"required","weapon.magicalBonus":1},[],["effect","weapon.baseItem"]],["Gants de nage et d'escalade","equipment","<p>Objet merveilleux, peu commun (nécessite un lien d'harmonisation). Tant que vous portez ces gants, vous avez une vitesse d'escalade et une vitesse de nage égales à votre vitesse, et vous bénéficiez d'un bonus de +5 aux tests de Force (Athlétisme) effectués pour grimper ou nager.</p>",{"rarity":"uncommon","attunement":"required"},[],["effect"]],["Chaussons d'araignée","equipment","<p>Objet merveilleux, peu commun (nécessite un lien d'harmonisation). Tant que vous portez ces chaussures légères, vous pouvez vous déplacer vers le haut, vers le bas et le long des surfaces verticales et des plafonds, en gardant les mains libres.</p>",{"rarity":"uncommon","attunement":"required"},[],["effect"]],["Marteau de foudre","weapon","<p>Arme (maillet d'armes ou marteau de guerre), légendaire (nécessite un lien d'harmonisation). Vous bénéficiez d'un bonus de +1 aux jets d'attaque et de dégâts effectués avec cette arme magique. L'arme possède 5 charges.</p>",{"rarity":"legendary","attunement":"required","weapon.magicalBonus":1},[],["effect","weapon.baseItem"]],["Cape du saltimbanque","equipment","<p>Objet merveilleux, rare. Cette cape sent légèrement le soufre. Quand vous la portez, vous pouvez lancer Porte dimensionnelle en tant qu'action magique. Cette propriété ne peut plus être utilisée avant l'aube suivante.</p>",{"rarity":"rare"},[],["effect"]],["Baguette d'éclairs","equipment","<p>Baguette, rare (nécessite un lien d'harmonisation avec un lanceur de sorts). Cette baguette possède 7 charges. Quand vous la tenez, vous pouvez dépenser 3 charges au maximum pour lancer Éclair (DD de sauvegarde 15). La baguette récupère 1d6 + 1 charges dépensées chaque jour à l'aube. Si vous dépensez la dernière charge de la baguette, lancez un d20. Sur un 1, la baguette tombe en cendres et est détruite.</p>",{"rarity":"rare","attunement":"required","attunementCondition":"un lanceur de sorts","consumable.type":"wand","consumable.charges":"7/dawn/1d6+1","consumable.destroyOnEmpty":true},[],["effect"]],["Cube de force","equipment","<p>Objet merveilleux, rare (nécessite un lien d'harmonisation). Ce cube mesure environ 2,5 cm de côté. Vous pouvez appuyer sur l'une de ses faces et dépenser les charges requises pour lancer le sort associé (DD de sauvegarde 17). Le cube commence avec 10 charges et récupère 1d6 charges dépensées chaque jour à l'aube.</p>",{"rarity":"rare","attunement":"required"},[],["effect","consumable.type","consumable.charges","consumable.destroyOnEmpty"]],["Hachette berserker","weapon","<p>(Nécessite un lien d'harmonisation) Vous bénéficiez d'un bonus de +1 aux jets d'attaque et de dégâts effectués avec cette arme magique. De plus, tant que vous êtes lié à cette arme, votre maximum de points de vie augmente de 1 par niveau que vous avez atteint.</p>",{"attunement":"required","weapon.magicalBonus":1,"weapon.baseItem":"handaxe"},[],["effect"]]];

const cases = EN.map(([id, name, expected, effects, ignore], i) => {
  const it = items.get(id);
  if ( !it || it.name !== name ) throw new Error(`item not found: ${id} ${name}`);
  return { id: `g-en-${i + 1}`, lang: "en", source: `${it.pack}/${it.name}`, name: it.name, itemType: it.type, html: it.html, expected, effects, ignore };
});
FR.forEach(([name, itemType, html, expected, effects, ignore = []], i) => {
  cases.push({ id: `g-fr-${i + 1}`, lang: "fr", source: "hand-written", name, itemType, html, expected, effects, ignore });
});
fs.writeFileSync(outFile, JSON.stringify({ description: "Third control set: compendium items and hand-written French items, truth annotated by hand from what each name and description state.", cases }, null, 1));
console.log(`en=${EN.length} fr=${FR.length}`);
